#!/bin/bash
# SPDX-License-Identifier: GPL-3.0-or-later
# Build Raysid.prg: writes the build date to source/BuildInfo.mc and compiles.
# Usage: bash build.sh [device]   (default fenix7xpro)
set -e
cd "$(dirname "$0")"
DEV="${1:-fenix7xpro}"
TC="${TOOLCHAIN:-/mnt/project-files/.toolchain}"
# Sequence number of the build sent for testing (for a compile check only,
# call monkeyc directly so the number is not incremented)
mkdir -p build
NUM=$(( $(cat build/build-number.txt 2>/dev/null || echo 0) + 1 ))
cat > source/BuildInfo.mc <<MC
// SPDX-License-Identifier: GPL-3.0-or-later
// Generated by build.sh, do not edit by hand
const APP_VERSION = "1.2";
const APP_YEAR = "2026";
const BUILD_DATE = "$(date +%-d.%-m.%Y)";
const BUILD_NUM = $NUM;
MC
bash "$TC/sdk/bin/monkeyc" -d "$DEV" -f monkey.jungle -o "build/Raysid-$DEV.prg" -y "$TC/developer_key.der" -l 3 -w
# The build number is saved only after a successful compile
echo "$NUM" > build/build-number.txt
[ "$DEV" = fenix7xpro ] && cp "build/Raysid-$DEV.prg" build/Raysid.prg
echo "OK build/Raysid-$DEV.prg (build $NUM)"
